import { randomUUID } from 'crypto';
import fs from 'fs';
import fsPromises from 'fs/promises';

type AtomicWriteOptions = {
  mode: number;
};

const temporaryPathFor = (filePath: string): string =>
  `${filePath}.${randomUUID()}.tmp`;

export const writeFileAtomicSync = (
  filePath: string,
  data: string,
  { mode }: AtomicWriteOptions,
): void => {
  const temporaryPath = temporaryPathFor(filePath);
  try {
    fs.writeFileSync(temporaryPath, data, { mode, flag: 'wx' });
    fs.chmodSync(temporaryPath, mode);
    fs.renameSync(temporaryPath, filePath);
  } catch (error) {
    fs.rmSync(temporaryPath, { force: true });
    throw error;
  }
};

export const writeFileAtomic = async (
  filePath: string,
  data: string,
  { mode }: AtomicWriteOptions,
): Promise<void> => {
  const temporaryPath = temporaryPathFor(filePath);
  try {
    await fsPromises.writeFile(temporaryPath, data, { mode, flag: 'wx' });
    await fsPromises.chmod(temporaryPath, mode);
    await fsPromises.rename(temporaryPath, filePath);
  } catch (error) {
    await fsPromises.rm(temporaryPath, { force: true });
    throw error;
  }
};
